from itertools import product
from typing import Sequence

def evaluate(coefficients: Sequence[int], x: int, prime: int) -> int:
    value = 0
    for coefficient in reversed(coefficients):
        value = (value * x + coefficient) % prime
    return value

def decode_exhaustively(prime: int, degree: int, locations: Sequence[int],
                        received: Sequence[int], errors: int) -> list[tuple[int, ...]]:
    if len(locations) != len(received):
        raise ValueError("locations and received must have equal length")
    if len({x % prime for x in locations}) != len(locations):
        raise ValueError("locations must be distinct")
    candidates: list[tuple[int, ...]] = []
    for coefficients in product(range(prime), repeat=degree + 1):
        mismatches = sum(evaluate(coefficients, x, prime) != y % prime
                         for x, y in zip(locations, received))
        if mismatches <= errors:
            candidates.append(coefficients)
    return candidates
